// Get all input items (Google Calendar events)
const events = $input.all().map(item => ({
  start: new Date(item.json.start.dateTime),
  end: new Date(item.json.end.dateTime),
}));

// Define working window (10:00 → 18:00 on same day)
const workDay = "2025-09-18"; // you could pass this dynamically
const startWindow = new Date(`${workDay}T10:00:00+03:00`);
const endWindow   = new Date(`${workDay}T18:00:00+03:00`);

// Sort events by start time
events.sort((a, b) => a.start - b.start);

let freeSlots = [];
let current = new Date(startWindow);

// Loop over each 1-hour block in working window
while (current < endWindow) {
  let slotStart = new Date(current);
  let slotEnd   = new Date(current.getTime() + 60 * 60 * 1000);

  // Check if this slot overlaps any event
  const overlaps = events.some(ev =>
    (slotStart < ev.end && slotEnd > ev.start) // overlap condition
  );

  // If no overlap, add slot to free slots
  if (!overlaps) {
    freeSlots.push({
      start: slotStart.toISOString(),
      end: slotEnd.toISOString()
    });
  }

  // Move forward 1 hour
  current = slotEnd;
}

return [
  {
    json: {
      freeSlots
    }
  }
];

const items = $input.all();

// Build output message
for (const item of items) {
  const freeSlots = item.json.freeSlots || [];

  let message = "";

  if (freeSlots.length > 0) {
    // Format available slots for display
    const slotList = freeSlots.map(slot => 
      `🕗 ${new Date(slot.start).toLocaleString('en-US', { timeZone: 'Asia/Beirut' })} → ${new Date(slot.end).toLocaleString('en-US', { timeZone: 'Asia/Beirut' })}`
    ).join('\n');

    message = `✅ Great! I found ${freeSlots.length} available time slot(s) for you at Daze Gallery:\n\n${slotList}\n\nPlease let me know which one works best for you! 😊`;
  } else {
    message = "😞 Sorry, no availability found in the selected time window. Would you like to try another date or time?";
  }

  // Replace entire item output
  item.json = {
    output: message
  };
}

return items;
